import sys

def max_permutation_value(N):
    if N == 1:
        return 0
    elif N == 2:
        return 6
    else:
        # For N >= 3, the pattern observed is:
        # (1 ⊕ 2) + (2 ⊕ 1) + (3 ⊕ 4) + (4 ⊕ 3) + ... + ((N-1) ⊕ N) + (N ⊕ (N-1))
        # Each pair (i, i+1) contributes 3 to the sum.
        # There are N//2 pairs if N is even, and (N-1)//2 pairs plus an extra term if N is odd.
        pairs = N // 2
        if N % 2 == 0:
            return 3 * pairs
        else:
            return 3 * pairs + (N // 2 + 1)

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    T = int(data[0])
    index = 1
    results = []

    for _ in range(T):
        N = int(data[index])
        index += 1
        results.append(max_permutation_value(N))

    print("\n".join(map(str, results)))

if __name__ == "__main__":
    main()
